svg.script:
const upload = document.getElementById('upload');
const fileInput = document.getElementById('file');
const statusText = document.getElementById('status');
const savedFiles = document.getElementById('saved-files');
let resultTab;
let choosingFile = false;
let databasePromise;

function openDatabase() {
  if (databasePromise) return databasePromise;
  databasePromise = new Promise((resolve, reject) => {
    if (!window.indexedDB) {
      reject(new Error('IndexedDB is unavailable.'));
      return;
    }
    const request = indexedDB.open('html-runner-library', 1);
    request.onupgradeneeded = () => {
      const database = request.result;
      database.createObjectStore('files', { keyPath: 'id' });
      database.createObjectStore('content');
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
    request.onblocked = () => reject(new Error('The local library is blocked.'));
  });
  return databasePromise;
}

function saveFile(file) {
  return openDatabase().then(database => new Promise((resolve, reject) => {
    const id = window.crypto && window.crypto.randomUUID ? window.crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
    const transaction = database.transaction(['files', 'content'], 'readwrite');
    transaction.objectStore('files').put({ id, name: file.name, size: file.size, savedAt: Date.now() });
    transaction.objectStore('content').put(file, id);
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error || new Error('Could not save the file.'));
    transaction.onabort = () => reject(transaction.error || new Error('Could not save the file.'));
  }));
}

function getSavedFiles() {
  return openDatabase().then(database => new Promise((resolve, reject) => {
    const request = database.transaction('files').objectStore('files').getAll();
    request.onsuccess = () => resolve(request.result.sort((first, second) => second.savedAt - first.savedAt));
    request.onerror = () => reject(request.error);
  }));
}

function getFileContent(id) {
  return openDatabase().then(database => new Promise((resolve, reject) => {
    const request = database.transaction('content').objectStore('content').get(id);
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  }));
}

function removeSavedFile(id) {
  return openDatabase().then(database => new Promise((resolve, reject) => {
    const transaction = database.transaction(['files', 'content'], 'readwrite');
    transaction.objectStore('files').delete(id);
    transaction.objectStore('content').delete(id);
    transaction.oncomplete = resolve;
    transaction.onerror = () => reject(transaction.error);
    transaction.onabort = () => reject(transaction.error);
  }));
}

function formatSize(bytes) {
  if (bytes < 1024) return `${bytes} B`;
  const units = ['KB', 'MB', 'GB', 'TB'];
  let size = bytes / 1024;
  let unit = 0;
  while (size >= 1024 && unit < units.length - 1) {
    size /= 1024;
    unit += 1;
  }
  return `${size.toFixed(size >= 10 ? 0 : 1)} ${units[unit]}`;
}

function getResultTab() {
  if (!resultTab || resultTab.closed) {
    resultTab = window.open('about:blank', '_blank');
    if (!resultTab) return null;
    return { tab: resultTab, created: true };
  }
  resultTab.focus();
  return { tab: resultTab, created: false };
}

function displayFile(tab, file, name) {
  const objectUrl = URL.createObjectURL(file);
  try {
    if (!tab.__htmlRunnerReady) {
      tab.document.open();
      tab.document.write('<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HTML file</title><style>html,body,iframe{width:100%;height:100%;margin:0;border:0;display:block}</style></head><body><iframe id="document"></iframe><script>window.addEventListener("pagehide",function(){if(window.opener&&window.__htmlObjectUrl)window.opener.URL.revokeObjectURL(window.__htmlObjectUrl)})<\/script></body></html>');
      tab.document.close();
      tab.__htmlRunnerReady = true;
    }
    const frame = tab.document.getElementById('document');
    const previousUrl = tab.__htmlObjectUrl;
    tab.__htmlObjectUrl = objectUrl;
    tab.document.title = name;
    if (previousUrl) {
      frame.addEventListener('load', () => {
        if (!tab.closed) frame.src = objectUrl;
      }, { once: true });
      frame.src = 'about:blank';
      URL.revokeObjectURL(previousUrl);
    } else {
      frame.src = objectUrl;
    }
  } catch (error) {
    URL.revokeObjectURL(objectUrl);
    throw error;
  }
}

function openSavedFile(entry) {
  const target = getResultTab();
  if (!target) {
    statusText.textContent = 'Allow pop-ups to open saved files.';
    return;
  }
  statusText.textContent = 'Opening ' + entry.name + '...';
  getFileContent(entry.id).then(file => {
    if (!file) throw new Error('Saved file is missing.');
    if (!target.tab.closed) displayFile(target.tab, file, entry.name);
    statusText.textContent = '';
  }).catch(() => {
    if (target.created && !target.tab.closed) target.tab.close();
    statusText.textContent = 'Could not open this saved file.';
  });
}

function renderLibrary() {
  return getSavedFiles().then(files => {
    savedFiles.replaceChildren();
    if (!files.length) {
      const empty = document.createElement('li');
      empty.className = 'empty-state';
      empty.textContent = 'No saved HTML files';
      savedFiles.append(empty);
      return;
    }
    for (const entry of files) {
      const row = document.createElement('li');
      const details = document.createElement('div');
      const name = document.createElement('div');
      const size = document.createElement('div');
      const actions = document.createElement('div');
      const open = document.createElement('button');
      const remove = document.createElement('button');
      name.className = 'file-name';
      name.textContent = entry.name;
      size.className = 'file-size';
      size.textContent = formatSize(entry.size);
      details.append(name, size);
      actions.className = 'file-actions';
      open.type = 'button';
      open.textContent = 'Open';
      open.setAttribute('aria-label', 'Open ' + entry.name);
      open.addEventListener('click', () => openSavedFile(entry));
      remove.type = 'button';
      remove.textContent = 'Remove';
      remove.setAttribute('aria-label', 'Remove ' + entry.name);
      remove.addEventListener('click', () => {
        remove.disabled = true;
        removeSavedFile(entry.id).then(renderLibrary).then(() => {
          statusText.textContent = 'Removed ' + entry.name + ' from this browser.';
        }).catch(() => {
          remove.disabled = false;
          statusText.textContent = 'Could not remove this file.';
        });
      });
      actions.append(open, remove);
      row.append(details, actions);
      savedFiles.append(row);
    }
  });
}

upload.addEventListener('click', () => {
  if (choosingFile || upload.disabled) return;
  choosingFile = true;
  fileInput.click();
});

fileInput.addEventListener('change', () => {
  choosingFile = false;
  const file = fileInput.files && fileInput.files[0];
  fileInput.value = '';
  if (!file) return;
  upload.disabled = true;
  upload.textContent = 'Saving...';
  statusText.textContent = 'Saving locally...';
  Promise.resolve().then(() => {
    if (navigator.storage && navigator.storage.persist) return navigator.storage.persist().catch(() => false);
  }).then(() => saveFile(file)).then(() => renderLibrary()).then(() => {
    statusText.textContent = 'Saved in this browser.';
  }).catch(() => {
    statusText.textContent = 'Could not save. Browser storage may be full or unavailable.';
  }).finally(() => {
    upload.disabled = false;
    upload.textContent = 'Upload HTML';
  });
});

fileInput.addEventListener('cancel', () => {
  choosingFile = false;
  fileInput.value = '';
});

renderLibrary().catch(() => {
  statusText.textContent = 'Local storage is unavailable in this browser context.';
});
